import type { Plugin, PluginContext } from "../../kernel/types";

// pricing 服务实例：total(n) = n * 21
const pricingService = {
  total: (n: number): number => n * 21,
};

const plugin: Plugin = {
  id: "pricing",
  name: "Pricing",
  version: "1.0.0",
  onLoad(ctx: PluginContext) {
    // 注册 service：id=pricing，value 为服务实例
    ctx.register({
      kind: "service",
      service: {
        id: "pricing",
        value: pricingService,
      },
    });

    // 注册 quote_total 工具：通过 ctx.inject("service:pricing").value 使用服务
    ctx.register({
      kind: "tool",
      tool: {
        name: "quote_total",
        version: "1.0.0",
        description: "通过 pricing 服务计算 total(n) = n * 21",
        permissions: {
          capabilities: [{ kind: "service", name: "pricing" }],
        },
        sideEffect: false,
        parameters: {
          type: "object",
          properties: {
            n: { type: "number", description: "数量 n" },
          },
          required: ["n"],
        },
        outputSchema: {
          type: "object",
          properties: {
            total: { type: "number", description: "计算结果 n*21" },
          },
          required: ["total"],
        },
        async handler(args: { n: number }, _tctx) {
          const handle = ctx.inject("service:pricing");
          const svc = handle.value;
          const total = svc.total(args.n);
          return { ok: true, data: { total } };
        },
      },
    });
  },
};

export default plugin;

